`ifndef RV32I_SEQ_ITEM_SV
`define RV32I_SEQ_ITEM_SV

import uvm_pkg::*;
`include "uvm_macros.svh"

class rv32i_seq_item extends uvm_sequence_item;
	
	// Random fields generated by Sequencer
	rand bit [31:0] instr;
	rand bit [31:0] data_rdata;
	
	// Monitored from DUT
	bit [31:0] instr_addr;
	bit [31:0] data_addr;
	bit [31:0] data_wdata;
	bit        mem_read;
	bit        mem_write;
	bit [3:0]  mem_write_mask;

	// UVM automation macros
	`uvm_object_utils_begin(rv32i_seq_item)
		`uvm_field_int(instr,          UVM_ALL_ON)
		`uvm_field_int(data_rdata,     UVM_ALL_ON)
		`uvm_field_int(instr_addr,     UVM_ALL_ON)
		`uvm_field_int(data_addr,      UVM_ALL_ON)
		`uvm_field_int(data_wdata,     UVM_ALL_ON)
		`uvm_field_int(mem_read,       UVM_ALL_ON)
		`uvm_field_int(mem_write,      UVM_ALL_ON)
		`uvm_field_int(mem_write_mask, UVM_ALL_ON)
	`uvm_object_utils_end

	// Constructor
	function new(string name = "rv32i_seq_item");
		super.new(name);
	endfunction

	// Constraints: Basic valid opcodes
	constraint valid_opcode_c {
		instr[6:0] inside {
			7'b0110011, // R-type
			7'b0010011, // I-type ALU
			7'b0000011, // LOAD
			7'b0100011, // STORE
			7'b1100011, // BRANCH
			7'b1101111, // JAL
			7'b1100111, // JALR
			7'b0110111, // LUI
			7'b0010111  // AUIPC
		};
	}
	
endclass

`endif
